#include <stdio.h>
#include <math.h>
int main() {
    double a, b, c, disc, x1, x2, realpart, imagpart;
    printf("请输入a, b, c:");
    scanf("%lf,%lf,%lf", &a, &b, &c);
    if (fabs(a) <= 1e-6)
        printf("不是二次方程\n");
    else {
        disc = b * b - 4 * a * c;
        if (fabs(disc) <= 1e-6)
            printf("有两个相等的实根: %8.4f\n", -b / (2 * a));
        else if (disc > 1e-6) {
            x1 = (-b + sqrt(disc)) / (2 * a);
            x2 = (-b - sqrt(disc)) / (2 * a);
            printf("有两个不等的实根: x1=%8.4f, x2=%8.4f\n", x1, x2);
        } else {
            realpart = -b / (2 * a);
            imagpart = sqrt(-disc) / (2 * a);
            printf("有两个共轭复根:\n");
            printf("x1=%8.4f+%8.4fi\n", realpart, imagpart);
            printf("x2=%8.4f-%8.4fi\n", realpart, imagpart);
        }
    }
    return 0;
}

