#include <stdio.h>

int main() {
    float scores[5][4] = {
        {80, 75, 92, 85},
        {60, 65, 70, 62},
        {90, 95, 88, 92},
        {75, 80, 78, 82},
        {85, 88, 86, 90}
    };
    float avg[5];
    int i, j, k;
    float temp_avg;
    float temp_score;

    // 1. 计算每个学生的平均成绩
    for (i = 0; i < 5; i++) {
        float sum = 0;
        for (j = 0; j < 4; j++) {
            sum += scores[i][j];
        }
        avg[i] = sum / 4.0;
    }

    // 2. 冒泡排序（同时交换平均分数组和成绩数组的行）
    for (i = 0; i < 4; i++) {
        for (j = 0; j < 4 - i; j++) {
            if (avg[j] < avg[j + 1]) {
                // 交换平均分
                temp_avg = avg[j];
                avg[j] = avg[j + 1];
                avg[j + 1] = temp_avg;

                // 交换对应的成绩行
                for (k = 0; k < 4; k++) {
                    temp_score = scores[j][k];
                    scores[j][k] = scores[j + 1][k];
                    scores[j + 1][k] = temp_score;
                }
            }
        }
    }

    // 3. 输出结果
    printf("排序后的成绩单（按平均分降序）：\n");
    for (i = 0; i < 5; i++) {
        printf("学生%d (平均分 %.2f): ", i + 1, avg[i]);
        for (j = 0; j < 4; j++) {
            printf("%.1f ", scores[i][j]);
        }
        printf("\n");
    }

    return 0;
}

