        loca = -1; // 超出范围直接判定找不到
    } else {
        while (sign == 0 && top <= bott) {
            mid = (top + bott) / 2;
            if (number == a[mid]) {
                loca = mid;
                sign = 1;
                printf("找到了，是数组中第 %d 个元素 (下标 %d)\n", loca + 1, loca);
            } else if (number > a[mid]) {
                // 因数组由大到小，若目标值大于中间值，则目标在左半区
                bott = mid - 1;
            } else {
                // 目标在右半区
                top = mid + 1;
            }
        }
    }

    if (sign == 0 || loca == -1) {
        printf("无此数\n");
    }

