// 求最大公约数
int gcd(int m, int n) {
    int r;
    while (n != 0) {
        r = m % n;
        m = n;
        n = r;
    }
    return m;
}

// 求最小公倍数
int lcm(int m, int n) {
    return (m * n) / gcd(m, n);
}

