void longest(char str[]) {
    int len = 0, max_len = 0, i = 0, index = 0, start = 0;
    while (str[i] != '\0') {
        if (str[i] != ' ') {
            len++;
        } else {
            if (len > max_len) {
                max_len = len;
                index = start;
            }
            len = 0;
            start = i + 1;
        }
        i++;
    }
    // 检查最后一个单词
    if (len > max_len) {
        max_len = len;
        index = start;
    }

    printf("最长的单词是：");
    for (i = index; i < index + max_len; i++)
        printf("%c", str[i]);
    printf("\n");
}
