// 2. 计算每门课平均分
void avg_cour() {
    int i, j;
    float s;
    for (j = 0; j < M; j++) {
        s = 0;
        for (i = 0; i < N; i++)
            s += score[i][j];
        a_cour[j] = s / N;
    }
}

