float highest() {
    float high = score[0][0];
    int i, j;
    r = 0; c = 0;
    for (i = 0; i < N; i++) {
        for (j = 0; j < M; j++) {
            if (score[i][j] > high) {
                high = score[i][j];
                r = i;
                c = j;
            }
        }
    }
    return high;
}

