void sort(int num[], char name[N][20]) {
    int i, j, temp_num;
    char temp_name[20];
    for (i = 0; i < N - 1; i++) {
        for (j = 0; j < N - 1 - i; j++) {
            if (num[j] > num[j + 1]) {
                temp_num = num[j];
                num[j] = num[j + 1];
                num[j + 1] = temp_num;

                strcpy(temp_name, name[j]);
                strcpy(name[j], name[j + 1]);
                strcpy(name[j + 1], temp_name);
            }
        }
    }
}

void search(int n, int num[], char name[N][20]) {
    int top = 0, bottom = N - 1, mid, flag = 1;
    if (n < num[0] || n > num[N - 1]) flag = 0;
    while (flag && top <= bottom) {
        mid = (top + bottom) / 2;
        if (n == num[mid]) {
            printf("找到职工，姓名：%s\n", name[mid]);
            return;
        } else if (n < num[mid])
            bottom = mid - 1;
        else
            top = mid + 1;
    }
    printf("未找到该职工号\n");
}

int main() {
    int num[N], number;
    char name[N][20];
    input(num, name);
    sort(num, name);
    printf("请输入要查找的职工号：");
    scanf("%d", &number);
    search(number, num, name);
