void reverse(int *x, int n) {
    int *p, temp, *i, *j, m = (n - 1) / 2;
    i = x;          // 指向首元素
    j = x + n - 1;  // 指向末元素
    p = x + m;      // 指向中间元素
    for (; i <= p; i++, j--) {
        temp = *i;
        *i = *j;
        *j = temp;
    }
}

