    if ((fpA = fopen("A", "r")) == NULL) { printf("无法打开文件A\n"); exit(0); }
    if ((fpB = fopen("B", "r")) == NULL) { printf("无法打开文件B\n"); exit(0); }
    if ((fpC = fopen("C", "w")) == NULL) { printf("无法打开文件C\n"); exit(0); }

    // 读取文件A的内容到数组
    while ((ch = fgetc(fpA)) != EOF) {
        str[n++] = ch;
    }
    // 读取文件B的内容到数组
    while ((ch = fgetc(fpB)) != EOF) {
        str[n++] = ch;
    }

    // 对数组进行冒泡排序
    for (i = 0; i < n - 1; i++) {
        for (j = 0; j < n - 1 - i; j++) {
            if (str[j] > str[j + 1]) {
                temp = str[j];
                str[j] = str[j + 1];
                str[j + 1] = temp;
            }
        }
    }

    // 将排序后的内容写入文件C
    for (i = 0; i < n; i++) {
        fputc(str[i], fpC);
    }

    fclose(fpA);
    fclose(fpB);
    fclose(fpC);
    printf("合并并排序完成。\n");
    return 0;
